initJs:
function(container, apiUrl, tables) {
  let editingModelId = null;

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#model-tbody');
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.model_name || ''}</td>
        <td>${r.target_store || ''}</td>
        <td>${r.product_categories || ''}</td>
        <td>${r.algorithm || ''}</td>
        <td>${r.accuracy_target || ''}%</td>
        <td><span style="padding: 2px 8px; border-radius: 4px; background: ${r.status === 'active' ? '#28a745' : '#6c757d'}; color: white; font-size: 12px;">${r.status || 'inactive'}</span></td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.id}">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}" style="margin-left: 4px;">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // 店舗選択肢を設定
  function setupStoreOptions() {
    const storeSelect = container.querySelector('#select-store');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = store.店舗名;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品カテゴリチェックボックスを設定
  function setupCategoryCheckboxes() {
    const categoryContainer = container.querySelector('#category-checkboxes');
    const productTable = tables.find(t => t.tableName === '商品マスタ');
    if (productTable && productTable.records) {
      const categories = [...new Set(productTable.records.map(p => p.商品カテゴリID).filter(Boolean))];
      categories.forEach(categoryId => {
        const label = document.createElement('label');
        label.style.display = 'block';
        label.style.marginBottom = '4px';
        label.innerHTML = `<input type="checkbox" value="${categoryId}" style="margin-right: 8px;">カテゴリ${categoryId}`;
        categoryContainer.appendChild(label);
      });
    }
  }

  // 重み付け合計値を更新
  function updateWeightTotal() {
    const weights = ['weight-sales', 'weight-weather', 'weight-event', 'weight-season'];
    let total = 0;
    weights.forEach(id => {
      const value = parseInt(container.querySelector(`#${id}`).value) || 0;
      total += value;
    });
    const totalSpan = container.querySelector('#weight-total');
    totalSpan.textContent = total;
    totalSpan.style.color = total === 100 ? 'var(--text)' : '#ff6a00';
  }

  // 学習率スライダーの値を表示
  function updateLearningRateDisplay() {
    const slider = container.querySelector('#input-learning-rate');
    const display = container.querySelector('#learning-rate-value');
    display.textContent = parseFloat(slider.value).toFixed(5);
  }

  // フォームをクリア
  function clearForm() {
    container.querySelector('#model-form').reset();
    container.querySelectorAll('#category-checkboxes input[type="checkbox"]').forEach(cb => cb.checked = false);
    container.querySelectorAll('input[name="prediction-period"]')[1].checked = true; // 30日をデフォルト
    container.querySelector('#weight-sales').value = 40;
    container.querySelector('#weight-weather').value = 20;
    container.querySelector('#weight-event').value = 20;
    container.querySelector('#weight-season').value = 20;
    updateWeightTotal();
    updateLearningRateDisplay();
    editingModelId = null;
  }

  // バリデーション
  function validateForm() {
    const modelName = container.querySelector('#input-model-name').value.trim();
    const targetStore = container.querySelector('#select-store').value;
    const categories = container.querySelectorAll('#category-checkboxes input[type="checkbox"]:checked');
    const learningStart = container.querySelector('#input-learning-start').value;
    const learningEnd = container.querySelector('#input-learning-end').value;
    const dataSources = container.querySelectorAll('input[type="checkbox"][id^="data-"]:checked');
    const algorithm = container.querySelector('#select-algorithm').value;
    const accuracyTarget = container.querySelector('#input-accuracy-target').value;
    const seasonality = container.querySelector('#input-seasonality').value;
    const weightTotal = parseInt(container.querySelector('#weight-total').textContent);

    if (!modelName) {
      alert('モデル名を入力してください。');
      return false;
    }

    if (!targetStore) {
      alert('対象店舗を選択してください。');
      return false;
    }

    if (categories.length === 0) {
      alert('商品カテゴリを選択してください。');
      return false;
    }

    if (!learningStart || !learningEnd) {
      alert('学習期間を設定してください。');
      return false;
    }

    if (new Date(learningStart) > new Date(learningEnd)) {
      alert('開始日は終了日より前の日付を設定してください。');
      return false;
    }

    if (new Date(learningStart) > new Date() || new Date(learningEnd) > new Date()) {
      alert('学習期間に未来の日付は設定できません。');
      return false;
    }

    if (dataSources.length === 0) {
      alert('データソースを選択してください。');
      return false;
    }

    if (!algorithm) {
      alert('アルゴリズムを選択してください。');
      return false;
    }

    if (!accuracyTarget || accuracyTarget < 0 || accuracyTarget > 100) {
      alert('モデル精度目標値は0-100%の範囲で入力してください。');
      return false;
    }

    if (seasonality && (isNaN(seasonality) || seasonality < 0)) {
      alert('季節性調整パラメータは数値で入力してください。');
      return false;
    }

    if (weightTotal !== 100) {
      alert('重み付けの合計値が100%でない旨のエラーメッセージが表示され、設定が保存されないこと。');
      return false;
    }

    return true;
  }

  // 初期設定
  setupStoreOptions();
  setupCategoryCheckboxes();
  updateWeightTotal();
  updateLearningRateDisplay();

  // 初期データを描画
  renderRows(tables[0].records || []);

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const keyword = container.querySelector('#input-search').value.trim();
    const rows = await window.aivicApi.list(0);
    if (rows) {
      const filtered = keyword ? rows.filter(r => JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())) : rows;
      renderRows(filtered);
    }
  });

  // 新規モデル作成ボタン
  container.querySelector('#btn-new-model').addEventListener('click', () => {
    clearForm();
    container.querySelector('#form-title').textContent = '新規モデル作成';
    container.querySelector('#model-list-section').classList.add('hidden');
    container.querySelector('#model-form-section').classList.remove('hidden');
  });

  // 一覧に戻るボタン
  container.querySelector('#btn-back-to-list').addEventListener('click', () => {
    container.querySelector('#model-form-section').classList.add('hidden');
    container.querySelector('#model-list-section').classList.remove('hidden');
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    container.querySelector('#model-form-section').classList.add('hidden');
    container.querySelector('#model-list-section').classList.remove('hidden');
  });

  // 学習率スライダー
  container.querySelector('#input-learning-rate').addEventListener('input', updateLearningRateDisplay);

  // 重み付け入力の監視
  ['weight-sales', 'weight-weather', 'weight-event', 'weight-season'].forEach(id => {
    container.querySelector(`#${id}`).addEventListener('input', updateWeightTotal);
  });

  // 保存ボタン
  container.querySelector('#btn-save-model').addEventListener('click', async () => {
    if (!validateForm()) return;

    const formData = {
      model_name: container.querySelector('#input-model-name').value.trim(),
      target_store: container.querySelector('#select-store').value,
      product_categories: Array.from(container.querySelectorAll('#category-checkboxes input[type="checkbox"]:checked')).map(cb => cb.value).join(','),
      learning_start_date: container.querySelector('#input-learning-start').value,
      learning_end_date: container.querySelector('#input-learning-end').value,
      prediction_period: container.querySelector('input[name="prediction-period"]:checked').value,
      data_sources: Array.from(container.querySelectorAll('input[type="checkbox"][id^="data-"]:checked')).map(cb => cb.value).join(','),
      algorithm: container.querySelector('#select-algorithm').value,
      learning_rate: parseFloat(container.querySelector('#input-learning-rate').value),
      seasonality_param: parseFloat(container.querySelector('#input-seasonality').value) || null,
      accuracy_target: parseInt(container.querySelector('#input-accuracy-target').value),
      outlier_removal: container.querySelector('#checkbox-outlier-removal').checked,
      weight_sales: parseInt(container.querySelector('#weight-sales').value),
      weight_weather: parseInt(container.querySelector('#weight-weather').value),
      weight_event: parseInt(container.querySelector('#weight-event').value),
      weight_season: parseInt(container.querySelector('#weight-season').value),
      status: 'active',
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString()
    };

    let result;
    if (editingModelId) {
      result = await window.aivicApi.update(0, editingModelId, formData);
    } else {
      // 重複チェック
      const existingRows = await window.aivicApi.list(0);
      if (existingRows && existingRows.some(r => r.model_name === formData.model_name)) {
        alert('このモデル名は既に使用されています。');
        return;
      }
      result = await window.aivicApi.save(0, formData);
    }

    if (result) {
      alert(editingModelId ? 'モデル設定が正常に変更されました。' : 'モデルが正常に作成されました。');
      container.querySelector('#model-form-section').classList.add('hidden');
      container.querySelector('#model-list-section').classList.remove('hidden');
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }
  });

  // 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    const editBtn = e.target.closest('.edit-btn');
    const deleteBtn = e.target.closest('.delete-btn');

    if (editBtn) {
      const id = editBtn.dataset.id;
      const rows = await window.aivicApi.list(0);
      const model = rows?.find(r => r.id === id);
      if (model) {
        editingModelId = id;
        container.querySelector('#form-title').textContent = 'モデル設定変更';

        // フォームに値を設定
        container.querySelector('#input-model-name').value = model.model_name || '';
        container.querySelector('#select-store').value = model.target_store || '';
        container.querySelector('#input-learning-start').value = model.learning_start_date || '';
        container.querySelector('#input-learning-end').value = model.learning_end_date || '';
        container.querySelector('#select-algorithm').value = model.algorithm || '';
        container.querySelector('#input-learning-rate').value = model.learning_rate || 0.01;
        container.querySelector('#input-seasonality').value = model.seasonality_param || '';
        container.querySelector('#input-accuracy-target').value = model.accuracy_target || '';
        container.querySelector('#checkbox-outlier-removal').checked = model.outlier_removal || false;

        // 予測期間
        if (model.prediction_period) {
          const radio = container.querySelector(`input[name="prediction-period"][value="${model.prediction_period}"]`);
          if (radio) radio.checked = true;
        }

        // カテゴリ選択
        if (model.product_categories) {
          const categories = model.product_categories.split(',');
          container.querySelectorAll('#category-checkboxes input[type="checkbox"]').forEach(cb => {
            cb.checked = categories.includes(cb.value);
          });
        }

        // データソース選択
        if (model.data_sources) {
          const sources = model.data_sources.split(',');
          container.querySelectorAll('input[type="checkbox"][id^="data-"]').forEach(cb => {
            cb.checked = sources.includes(cb.value);
          });
        }

        // 重み付け設定
        container.querySelector('#weight-sales').value = model.weight_sales || 40;
        container.querySelector('#weight-weather').value = model.weight_weather || 20;
        container.querySelector('#weight-event').value = model.weight_event || 20;
        container.querySelector('#weight-season').value = model.weight_season || 20;

        updateWeightTotal();
        updateLearningRateDisplay();

        container.querySelector('#model-list-section').classList.add('hidden');
        container.querySelector('#model-form-section').classList.remove('hidden');
      }
    }

    if (deleteBtn) {
      if (!confirm('削除しますか？')) return;
      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(0, id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }
  });
}
